INSERT OR IGNORE INTO material_catalog (id,curricular_unit_id,lesson_id,material_kind,bibliography_format,title,description,file_name,mime_type,storage_backend,storage_key,storage_state,byte_size,checksum_sha256,verification_status,publication_status,public_access,source_id,page_note,version_group,version_number,is_recommended,created_at,updated_at) SELECT 'material-biblio-2627-ap6-nolte7-translation',cu.id,'lesson-neuro-ap6','bibliography','translation','Nolte’s The Human Brain — AP6 · Tradução','Bibliografia traduzida para AP6. 171 páginas e 80 figuras numeradas, distribuídas por 81 páginas de figuras.','AP6_Nolte_Bibliografia_Traduzida_2026-10-10.pdf','application/pdf','r2','materials/neuroanatomia/bibliografia/traducoes/2026-27/AP6_Nolte_Bibliografia_Traduzida_2026-10-10.pdf','ready',31688265,'fd5399f61ec8b9eac6e0df51c27c6e92b183ddb20bc56179dcfc85ae46aaf63f','verified','published',0,'source-nolte-7','Nolte, 7.ª edição: pp. 272–295; 495–523; 394–411; 579–590.','biblio-2627-ap6-nolte7-translation',1,1,unixepoch()*1000,unixepoch()*1000 FROM curricular_units cu WHERE cu.code='NEURO' AND cu.active=1 AND EXISTS(SELECT 1 FROM material_sources WHERE id='source-nolte-7') AND EXISTS(SELECT 1 FROM material_lessons WHERE id='lesson-neuro-ap6');

